-- V6: 현재 도메인 모델대로 스키마 재구축 (V5에서 전부 드롭한 뒤)
--   * V1~V4의 최종 상태 + 프로필 이미지 프리셋 전환을 한 번에 반영한다.
--   * service_user.profile_image_url(자유 URL) → profile_image(프리셋 번호, 1부터)
--   * trip은 팟의 한 번의 방문(지역 + 기간 + 키워드), trip_record는 그 방문의 멤버별 기록,
--     trip_image는 trip이 아니라 trip_record에 매달린다.
--   * FK 제약은 두지 않는다 — 참조 무결성은 애플리케이션 레이어에서 보장한다.
--     대신 조인/조회 경로를 받쳐주는 인덱스는 그대로 유지한다.
--   * region은 프론트 지도(GeoJSON)와 코드를 맞춰 시딩까지 함께 한다.
-- Oracle(ATP)과 H2(MODE=Oracle) 양쪽에서 동일하게 동작해야 한다.
--   → INSERT ALL / SELECT ... FROM DUAL 같은 Oracle 전용 문법은 쓰지 않는다.

CREATE TABLE service_user (
    id                 NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nickname           VARCHAR2(40)   NOT NULL,
    -- 서버가 정의한 프리셋 아바타 번호. 기본값 1.
    profile_image      NUMBER(2)      DEFAULT 1 NOT NULL,
    created_at         TIMESTAMP      DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at         TIMESTAMP      DEFAULT CURRENT_TIMESTAMP NOT NULL
);

-- 자연키(행정구역 코드) 테이블.
-- region_code는 CHAR가 아니라 VARCHAR2다 — CHAR(5)는 공백 패딩이라 광역시 코드 '11'이
-- '11   '로 저장돼 GeoJSON properties.code('11')와 비교가 어긋난다.
CREATE TABLE region (
    region_code        VARCHAR2(5)    PRIMARY KEY,
    region_name        VARCHAR2(50)   NOT NULL,  -- 정식 행정구역명 (예: 서울특별시)
    display_name       VARCHAR2(50)   NOT NULL,  -- 지도/UI 표시명 (예: 서울)
    region_level       VARCHAR2(10)   NOT NULL,  -- metro | city | county
    base_year          CHAR(4)        NOT NULL,  -- 행정구역 경계 기준연도
    name_eng           VARCHAR2(60),             -- 영문명 (원본 미제공 시 NULL)
    geo_source         VARCHAR2(50)   NOT NULL,  -- 원본 GeoJSON 소스 식별자
    created_at         TIMESTAMP      DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at         TIMESTAMP      DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_region_level CHECK (region_level IN ('metro', 'city', 'county'))
);

CREATE TABLE social_account (
    id                 NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    service_user_id    NUMBER(19)     NOT NULL,
    provider           VARCHAR2(20)   NOT NULL,
    provider_user_id   VARCHAR2(150)  NOT NULL,
    provider_email     VARCHAR2(320),
    created_at         TIMESTAMP      DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at         TIMESTAMP      DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT uq_social_account_provider UNIQUE (provider, provider_user_id)
);

CREATE TABLE party (
    id                 NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    party_name         VARCHAR2(100)  NOT NULL,
    invite_code        VARCHAR2(12)   NOT NULL,
    owner_id           NUMBER(19)     NOT NULL,
    created_at         TIMESTAMP      DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at         TIMESTAMP      DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT uq_party_invite_code UNIQUE (invite_code)
);

CREATE TABLE party_member (
    id                 NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    party_id           NUMBER(19)     NOT NULL,
    service_user_id    NUMBER(19)     NOT NULL,
    -- 여행 기록 아코디언의 팟원 정렬(가입 순서)에 쓴다. 정렬은 (created_at, id)로 한다.
    created_at         TIMESTAMP      DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT uq_party_member UNIQUE (party_id, service_user_id)
);

CREATE TABLE image (
    id                 NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    original_url       VARCHAR2(512)  NOT NULL,
    thumbnail_url      VARCHAR2(512),
    uploader_id        NUMBER(19),
    -- presigned URL 발급 시점에 확정되는 스토리지 키. 업로드 검증(HEAD)/삭제가 이 키로 동작한다.
    -- 업로드 여부의 source of truth는 스토리지이므로 상태 컬럼은 두지 않는다.
    object_key         VARCHAR2(200)  NOT NULL,
    created_at         TIMESTAMP      DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT uq_image_object_key UNIQUE (object_key)
);

CREATE TABLE trip (
    id                 NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    party_id           NUMBER(19)     NOT NULL,
    -- region.region_code와 타입을 맞춘다 (VARCHAR2, 패딩 없음)
    region_code        VARCHAR2(5)    NOT NULL,
    -- 기록하기 플로우의 키워드 선택이 기존 color를 대체한다.
    keyword            VARCHAR2(20)   NOT NULL,
    start_date         DATE           NOT NULL,
    end_date           DATE           NOT NULL,
    created_by         NUMBER(19),
    created_at         TIMESTAMP      DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at         TIMESTAMP      DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE trip_record (
    id                 NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    trip_id            NUMBER(19)     NOT NULL,
    service_user_id    NUMBER(19)     NOT NULL,
    -- COMMENT는 Oracle 예약어라 컬럼명을 comment_text로 둔다
    comment_text       VARCHAR2(500),
    created_at         TIMESTAMP      DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at         TIMESTAMP      DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT uq_trip_record UNIQUE (trip_id, service_user_id)
);

CREATE TABLE trip_image (
    id                 NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    trip_record_id     NUMBER(19)     NOT NULL,
    image_id           NUMBER(19)     NOT NULL,
    image_date         DATE,
    created_at         TIMESTAMP      DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT uq_trip_image UNIQUE (trip_record_id, image_id)
);

-- 참조 컬럼 인덱스. UNIQUE 제약이 선두 컬럼으로 커버하는 경로
-- (trip_record.trip_id, trip_image.trip_record_id, party_member.party_id)는 별도로 만들지 않는다.
CREATE INDEX idx_social_account_user ON social_account (service_user_id);
CREATE INDEX idx_party_owner ON party (owner_id);
CREATE INDEX idx_party_member_member ON party_member (service_user_id);
CREATE INDEX idx_image_uploader ON image (uploader_id);
CREATE INDEX idx_trip_party ON trip (party_id);
CREATE INDEX idx_trip_region ON trip (region_code);
CREATE INDEX idx_trip_creator ON trip (created_by);
CREATE INDEX idx_trip_record_user ON trip_record (service_user_id);
CREATE INDEX idx_trip_image_image ON trip_image (image_id);

-- =====================================================================
-- region 시딩 (168건)
--   출처: southkorea/southkorea-maps kostat 2018
--     - skorea-provinces-2018-topo-simple.json      (metro 8)
--     - skorea-municipalities-2018-topo-simple.json (city 78 / county 82)
--   프론트 src/shared/lib/loadKoreaGeoJson.ts가 렌더하는 지역과 1:1로 맞춘다.
--   '-merged-gu' 소스는 자치구가 있는 시(수원/성남/…)를 시 단위로 합친 것이라
--   원본에 영문명이 없어 name_eng가 NULL이다.
--   created_at/updated_at은 컬럼 DEFAULT로 채운다 (SYSTIMESTAMP는 Oracle 전용).
-- =====================================================================

-- 원본 GeoJSON의 nameEng 오류(Gongju-si)를 그대로 보존한다 — 프론트 키와 어긋나지 않게 하기 위함.
